const menuButton=document.querySelector('.menu-button');const nav=document.querySelector('.nav');menuButton?.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav?.addEventListener('click',e=>{if(e.target.closest('a')){menuButton.setAttribute('aria-expanded','false');nav.classList.remove('open')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.focus()}});const search=document.querySelector('#region-search');search?.addEventListener('input',()=>{const query=search.value.toLocaleLowerCase('tr').trim();let total=0;document.querySelectorAll('.location').forEach(item=>{const match=item.textContent.toLocaleLowerCase('tr').includes(query);item.hidden=!match;if(match)total++});document.querySelector('#result-count').textContent=total+' hizmet noktası gösteriliyor.'});
